 sfx(kind){if(!this.ctx||!this.app.settings.sound)return;if(kind==='slash'||kind==='dash'){const s=this.ctx.createBufferSource(),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();s.buffer=this.noise;f.type='highpass';f.frequency.value=kind==='slash'?900:1700;g.gain.value=.35;s.connect(f);f.connect(g);g.connect(this.master);s.start();return;}const freqs={jump:500,land:85,spell:760,hit:140,hurt:90,heal:580,rune:920,sigil:1100,checkpoint:620,rank:880,upgrade:740,defeat:180};this.tone(freqs[kind]||400,kind==='hurt'?.22:.14,kind==='hit'||kind==='hurt'?'triangle':'sine',kind==='hurt'?.5:.3);if(['sigil','checkpoint','rank','heal','upgrade'].includes(kind)){this.tone(880,.5,'sine',.18,.12);this.tone(1174,.8,'sine',.13,.26);}}
