 newDialog(){const d=this.settings.difficulty;this.modal('Choose your journey',`<p>Tomorrow is yours to fight for. All three journeys include the complete story and both ending choices.</p><div class="difficulty"><button data-diff="story" class="${d==='story'?'selected':''}" aria-pressed="${d==='story'}"><strong>Storykeeper</strong><span>Half incoming damage. More time to read the world.</span></button><button data-diff="adventure" class="${d==='adventure'?'selected':''}" aria-pressed="${d==='adventure'}"><strong>Wayfarer</strong><span>The intended balance of discovery and swordplay.</span></button><button data-diff="veteran" class="${d==='veteran'?'selected':''}" aria-pressed="${d==='veteran'}"><strong>Emberbound</strong><span>Enemies hit 35% harder. Every dash matters.</span></button></div><div class="modal-buttons"><button class="primary" data-act="launch" data-primary>Enter Moonroot →</button><button class="secondary" data-act="import">Import journey</button></div><p class="fine" style="margin-top:17px">${this.savedStory?'Starting again replaces the active journey. The previous valid save is kept as a rolling backup.':'Your progress saves at beacons and discoveries. Export a copy anytime from Pause.'}</p>`,'new');}
